SELECT p.subject_id, h.hadm_id, COUNT(DISTINCT CASE WHEN l.itemid = 757071 AND l.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '12 hours' THEN l.subject_id END) AS glp1_initiation_12h, COUNT(DISTINCT CASE WHEN l.itemid = 757071 AND l.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') AND a.dischtime THEN l.subject_id END) AS glp1_prevalence_72h, (COUNT(DISTINCT CASE WHEN l.itemid = 757071 AND l.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '12 hours' THEN l.subject_id END) - COUNT(DISTINCT CASE WHEN l.itemid = 757071 AND l.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') AND a.dischtime THEN l.subject_id END)) * 100.0 / NULLIF(COUNT(DISTINCT CASE WHEN l.itemid = 757071 AND l.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '12 hours' THEN l.subject_id END), 0) AS percentage_change FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 50 AND 60 AND l.itemid IN (757071, 757072) AND l.charttime BETWEEN a.admittime AND a.dischtime AND (a.dischtime - a.admittime) >= 72 GROUP BY p.subject_id, h.hadm_id;